const SCALE = 32;
const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function decodeRings(encoded, scale, alphabet) {
  const index = new Map([ ...alphabet ].map((c, i) => [ c, i ]));
  const rings = [];
  for (const chunk of encoded.split("|")) {
    const ring = [];
    let i = 0, x = 0, y = 0;
    const read = () => {
      let mul = 1, result = 0, byte;
      do {
        byte = index.get(chunk[i++]);
        result += (byte % 32) * mul;
        mul *= 32;
      } while (byte >= 32);
      return result % 2 ? -(result + 1) / 2 : result / 2;   // un-zigzag
    };
    while (i < chunk.length) {
      x += read();
      y += read();
      ring.push([ y / scale - 90, x / scale - 180 ]);
    }
    if (ring.length > 2) rings.push(ring);
  }
  return rings;
}

const cache = new Map();

// Closed rings of [lat, lon] for one country, or null. Decoded on first ask
// and kept: a choropleth wants every country, a tooltip wants one.
export function countryRings(iso) {
  const key = String(iso || "").toUpperCase();
  if (cache.has(key)) return cache.get(key);
  const entry = RAW[key];
  const rings = entry ? decodeRings(entry[1], SCALE, ALPHABET) : null;
  cache.set(key, rings);
  return rings;
}

export const countryName = (iso) => RAW[String(iso || "").toUpperCase()]?.[0] ?? null;
export const countryCodes = () => Object.keys(RAW);
